//! 🧪️ Native receipt conservation and malformed identity refusal use the real original paid ledger.
use super::*;
fn heap<T>(body:impl FnOnce()->T)->(T,(usize,usize)){let(value,heap)=semio_framework_trace::observe_heap_allocations_on_this_thread(body);(value,(heap.requested_bytes,heap.released_bytes))}
#[test]
fn original_retained_turn_receipt_roundtrips_all_identity_axes_and_rejects_every_forged_currency(){
 let fixture=include_str!("🧫️fixtures/🔣️.json");let oracle:RetainedTurnReceipt=serde_json::from_str(fixture).unwrap();let original:RetainedTurnReceipt=semio_framework_pack_json::from_json_str(fixture,semio_framework_pack_json::JsonMemberPolicy::Reject).unwrap();assert_eq!(original,oracle);let input=original.input;let input_pointer=&input as*const _;
 let(admitted,measured)=heap(||semio_framework_job::JobPayloadAuthority::admit(semio_framework_job::OperationId(input.operation),semio_framework_job::Generation(input.generation),input.grant).unwrap());let(mut authority,birth)=admitted.unwrap();assert_eq!((birth.retained_capacity_bytes,birth.released_bytes),measured);assert_eq!(birth,original.spent);let(receipt,measured)=heap(||input.return_original(birth,original.work_units_spent).unwrap());assert_eq!(measured,(0,0));assert_eq!(receipt,original);assert_eq!(&input as*const _,input_pointer);
 for altered in [RetainedTurnInput{operation:input.operation+1,..input},RetainedTurnInput{generation:input.generation+1,..input},RetainedTurnInput{epoch:input.epoch+1,..input},RetainedTurnInput{work:OriginalActorTurnWork{clock_binding:input.work.clock_binding+1,..input.work},..input},RetainedTurnInput{work:OriginalActorTurnWork{absolute_deadline_us:input.work.absolute_deadline_us+1,..input.work},..input},RetainedTurnInput{work:OriginalActorTurnWork{fuel:input.work.fuel+1,..input.work},..input},RetainedTurnInput{grant:RetainedCloneGrant{maximum_depth:input.grant.maximum_depth+1,..input.grant},..input}]{let(result,measured)=heap(||receipt.validate_for(altered));assert!(result.is_err());assert_eq!(measured,(0,0));assert_eq!(&input as*const _,input_pointer);}
 for spent in [RetainedCloneProgress{copied_items:input.grant.maximum_items+1,..birth},RetainedCloneProgress{copied_bytes:input.grant.maximum_copy_bytes+1,..birth},RetainedCloneProgress{retained_capacity_bytes:input.grant.maximum_capacity_bytes+1,..birth},RetainedCloneProgress{released_bytes:input.grant.maximum_release_bytes+1,..birth}]{let(result,measured)=heap(||input.return_original(spent,original.work_units_spent));assert!(result.is_err());assert_eq!(measured,(0,0));}
 let corrupt=RetainedTurnReceipt{remaining:RetainedCloneGrant{maximum_release_bytes:receipt.remaining.maximum_release_bytes-1,..receipt.remaining},..receipt};let(result,measured)=heap(||corrupt.validate_for(input));assert!(result.is_err());assert_eq!(measured,(0,0));
 let(result,measured)=heap(||input.return_original(birth,input.work.fuel+1));assert!(result.is_err());assert_eq!(measured,(0,0));let forged_fuel=RetainedTurnReceipt{remaining_fuel:receipt.remaining_fuel+1,..receipt};let(result,measured)=heap(||forged_fuel.validate_for(input));assert!(result.is_err());assert_eq!(measured,(0,0));
 let mut bytes=Vec::with_capacity(192);let cursor=bytes.as_ptr();let(result,measured)=heap(||semio_framework_async::poll::resolve_ready(receipt.pack_encode(&mut bytes)));result.unwrap();assert_eq!(measured,(0,0));assert_eq!(bytes.as_ptr(),cursor);let mut position=0;let(decoded,measured)=heap(||semio_framework_async::poll::resolve_ready(RetainedTurnReceipt::pack_decode(&bytes,&mut position)));assert_eq!(decoded.unwrap(),receipt);assert_eq!(measured,(0,0));assert_eq!(position,bytes.len());assert_eq!(bytes.len(),176);assert_eq!(semio_framework_pack_json::to_json_string(&receipt),semio_framework_pack_json::to_json_string(&oracle));
 let(step,measured)=heap(||authority.close_step(input.grant).unwrap());assert_eq!((step.progress().retained_capacity_bytes,step.progress().released_bytes),measured);assert_eq!(birth.retained_capacity_bytes,step.progress().released_bytes);let(_,measured)=heap(||drop(authority));assert_eq!(measured,(0,0));
}
